insert into book_contents (book_id, chapter_no, title, body) values
  ('0000b101-0000-4000-8000-000000000101', 1, '1장',
   '몹시 어두운 날 밤이었습니다. 도적 두 명이 어느 고래등같이 큰 집 담을 넘어서 몰래 들어왔습니다. 그 집 안의 동정을 살핀 뒤에 도적은 서로 얼굴을 바라다보면서,

“잠들은 모양이지?”

“그런 모양일세. 내가 먼저 들어가 보지.”

하고 중얼거리더니, 앞장선 도적이 뒤에 있는 도적을 돌아다보면서,

“내 다녀 나올 테니, 자네는 거기 서서 망이나 보게.”

하고, 말하였습니다. 그러니까, 뒤떨어진 도적은 걸음을 멈추고 서더니,

“그럼, 얼른 일을 잘 해 가지고 나오게.”

하고, 대답 겸 부탁을 하였습니다.

앞장선 도적은 사면을 두리번두리번 둘러보면서 서 있었습니다.

망을 보고 서 있는 도적의 머리 위에는 감나무 가지가 늘어져 있었는데, 그 때는 마침 늦은 가을이기 때문에 무르익은 연시가 가지마다 더덕더덕 열려 있었습니다.

그 무르익은 연시 중에서 제일 잘 익은 감 한 개가 저절로 정신없이 서 있는 도적의 목덜미에 떨어지면서 그냥 터져 버렸습니다.

“에그머니!”

겁쟁이 도적이 얼떨결에 놀라 소리를 쳤습니다. 가뜩이나 겁이 나서 가슴이 두근거리는 판에 무엇인지 알지 못하는 것이 목덜미를 후려치는 바람에 화살을 맞은 것이나, 칼에 맞은 줄로만 꼭 알았던 것입니다.

그리고 더구나 목덜미를 만져 보니까, 끈적끈적한 물이 손에 묻지를 않겠습니까.

이 겁쟁이 도적은 자기가 생각해도 산 것 같지 않았습니다. 그 때 집 안에서 훔칠 것을 다 훔쳐 가지고, 먼저 들어갔던 도적이 뛰어나오더니, 쭈그리고 앉아서 어쩔 줄 모르는 그 친구를 바라보자마자,

“여보게, 왜 그러나? 응…….”

하고, 그 앞으로 가까이 가면서 물었습니다.

“목덜미를 맞았어……, 목덜미를!”

하고, 겁쟁이 도적이 떨리는 목소리로 대답하는 소리를 듣더니,

“무엇이 어째? 목덜미를 맞다니.”

하고, 재차 물었습니다.

“여보게, 여길 좀 만져 보게…….”

하고, 겁쟁이가 말하는 대로 목덜미를 만져 보더니, 놀라는 목소리로 중얼거렸습니다.

“아이그, 끈적끈적한 게 틀림없는 피인걸 피야…….”

“피가 이렇게 나도록 상했으니, 나는 아마 이만 살고 죽나 보이.”

하고, 겁쟁이는 풀이 하나도 없이 말합니다.

“그거야 될 말인가. 밝은 데 가서 보아야 알지. 자아, 내 등에 업히게, 내 데려다 줄 테니…….”

하고, 잡아 일으키는 것도 듣지 않고 겁쟁이는,

“아닐세, 나는 더 살지 못하고 인제는 죽네. 이 꼴을 하고, 집엔 가서 무얼 하나, 처음에도 피가 그렇게 묻었으니, 지금은 마구 쏟아지겠지, 여보게 이왕이면, 이 모가지를 얼른 잘라 주게 응! 어서…….”

하고, 애걸하다시피 하였습니다.

“아! 그래. 그렇게까지 괴롭단 말인가? 그럼 어쩔 수 없이 자네가 목을 베어 달라니까 베이는 걸세.”

하고, 겁쟁이의 목을 칼로 베었습니다.

그래서 목 없는 시체와 따로 떨어진 목을 가지고 도적은 겁쟁이 집을 찾아가서, 지낸 일을 다 이야기하고 몹시 슬퍼하였습니다.

집안 사람들은 의심스럽고 또 놀라워서 울며불며 동강난 목을 자세히 살펴보니까, 칼이나 화살 자리는커녕 손톱 자국 하나 없었습니다. 그래서 집안사람들은 도적의 말을 믿지 않는 빛을 보였습니다.

그러니까 도적은,

“아니올시다. 거짓 말씀을 여쭐 리가 있습니까? 목덜미를 맞았으니, 어서 목을 잘라 주게 하고, 너무도 애걸을 하기에 여북 아프기에 저럴까 하고 딱해서 그대로 목을 베었습니다.”

하고 말하였습니다.'),
  ('0000b102-0000-4000-8000-000000000102', 1, '1장',
   '옛날, 어느 산 속에 조그만 집 한 채가 있고, 그 집에 노파 한 분이 젖먹이 어린아기 하나를 얻어다가 기르고 있었습니다.

그리고, 그 집 뒤꼍 담 안에 올빼미 한 마리와 까치 한 마리가 있었는데, 올빼미와 까치는 서로 매우 친하게 지내고 또 주인 노파에게도 퍽 친하게 굴었습니다.

하루는 밤에 노파가 마을에 볼일이 있어서 가기는 가야겠는데, 어린애 때문에 염려가 되어서, 얼른 가지를 못하고 주저주저하고 있었습니다. 이 밤중에 이 깊은 산 속에 아기를 두고 가도 괜찮을까 하고, 한참이나 망설이다가 언뜻 생각이 나서, 뒤꼍에 가서 나무 위에 있는 올빼미와 까치를 보고,

“내가 마을에 잠깐 다녀올 것이니, 너희가 그 동안에 우리 아기를 잘 보아다구. 그 대신 잘만 보아 주면 내가 상으로 옷을 한 벌씩 만들어 줄 것이니…….” 하였습니다.

그러니까,

“예, 그러겠습니다.”

하고 대답하는 듯이 까치는 깍깍 울고, 올빼미는 꾸룩 꾸룩 울었습니다.

노파는 대답을 듣고 안심하고 마을로 내려갔습니다. 깊은 산 속에 다만 한 채 있는 이 집에, 어린이 하나만 누워 있고, 밤은 점점 깊어 갔습니다. 캄캄한 산 속 저 밑에서 물 소리만 출렁출렁 나고, 바람이 쏴아 불고 몹시 무서웠습니다. 그래도, 무서움을 아니 타고 올빼미와 까치는 나뭇가지에서 자지 않고, 앉아서 지키고 있었습니다. 밤은 점점 깊어만 갔습니다.

그 때, 나무 밑에서 쏴아 하는 소리가 나더니, 밤눈 밝은 올빼미가 눈을 둥그렇게 뜨고 내려다보니까, 아아 큰일 났습니다. 보기에도 무서운 시커먼 구렁이가, 어린애가 자는 방을 향해서 자꾸 갑니다. 그래서, 깜짝 놀라서 이것 큰일 났다고 까치를 보고 자꾸 울었습니다. 그 소리를 듣고 까치도 정신을 차려 보니까, 큰 구렁이가 어린애 방으로 가는 것이 보였습니다. 큰일 났다고, 까치가 자꾸 깍깍 깍깍 울어서, 동무를 불렀습니다. 아닌 밤중에 군호 소리를 듣고, 까치 떼가 금시에 몰려왔습니다. 수많은 까치가 힘을 합하여 구렁이 몸뚱이를 쪼았습니다. 그 때 벌써 구렁이는 방 문턱에까지 왔으나, 까치 떼에게 뜯겨서 필경 죽어 늘어졌습니다.

구렁이가 죽는 것을 보고야 까치 떼는 헤어졌습니다. 올빼미와 까치는 혼이 나서 눈을 크게 뜨고, 또 지켰습니다. 얼마 아니 있어서, 마을에 갔던 노파가 다 꺼져 가는 등불을 들고, 어린애가 잘이나 있나? 하면서, 급히 돌아왔습니다. 오니까, 올빼미와 까치가 방문 앞에까지 와서 자꾸 우는 까닭에, 가서 등불을 밝혀 보니까, 거기 구렁이 한 마리가 몹시 뜯겨서, 피를 흘리고 죽어 늘어져 있었습니다. 노파는 어린애를 끼어안고 기뻐하면서,

“우리 복덩이 잘도 잔다. 오오! 까치야 올빼미야, 기특하다. 너희가 아니었다면, 큰일 날 뻔하였구나! 내가 내일 좋은 옷을 지어 줄 것이니, 오늘은 편히들 자거라.”

하였습니다.

이튿날이 되어 노파는 약속대로 옷을 만들되, 올빼미에게는 얼룩덜룩하게 무늬 놓은 옷을 해 주고, 까치에게는 하얀 비단옷을 해 주었습니다. 그런데, 올빼미는 진드근하니까, 옷도 얼른 몸에 맞도록 잘 되어서 먼저 입었지만, 까치는 하얀 비단옷 입는 게 좋아서 자꾸 겅정겅정 뛰어 돌아다녔습니다. 노파가 옷을 대강 만들어서 맞는지 안 맞는지 보려고, 한 번 입혀 보았습니다.

“이 얘야, 좀 진드근하게 있거라. 어디 맞나 안 맞나 보자.”

하여도, 까치는 옷을 입더니, 그만 무한 기뻐서 자꾸 겅정겅정 뛰어 돌아다녔습니다. 너무 그러니까, 노파도 성이 났습니다.

“글쎄, 이리 좀 오너라. 맞나 안 맞나 보자. 그렇게 말을 안 들으면, 그 때때옷에 검정 물을 끼얹을 테다.”

하여도, 까치는 그저 새 옷 입는 게 좋아서, 자꾸 뛰어다니기만 했습니다.

“그래도 안 올 테냐?”

소리를 질러도 까치는 기뻐서 뛰느라고 듣지도 못하고, 그저 좋아서 겅정겅정 뛰어 돌아다니기만 했습니다. 노파는 참다 참다 못해서,

“예끼, 이 녀석!”

하고, 옆의 대야에 있던 검정 물을 내어 끼얹었습니다.

까치는 겅정겅정 뛰다가, 머리에서부터 검정 물을 뒤집어 쓰고, 그 하얗던 비단 옷까지 까맣게 되었습니다. 그리고, 다만 배때기만 물을 안 맞아서, 하얀 채로 있었습니다. 그래도, 까치는 그저 새 옷 입는 게 좋아서, 그저 겅정겅정 뛰어다녔습니다.

그래서, 까치는 등이 까맣고, 지금까지도 그 옷을 그대로 입고 좋아서 겅정겅정 뛰어다닌답니다.'),
  ('0000b103-0000-4000-8000-000000000103', 1, '1장',
   '지금으로부터 한 삼십 년 전 일입니다. 서울 새문 밖 어떤 능에서 제사 때에 쓰는, 은으로 만든 제사 그릇 여섯 개를 잃어버렸습니다.

“큰일 났다!”

하고 그 능에 드나드는 사람마다 얼굴빛이 변하여 어쩌나 어쩌나 하고 걱정 걱정하지마는 그 중에도 능참봉은 자기에게 책임이 있는 일이라 걱정과 근심이 대단하여 병이 날 지경이었습니다.

‘암만해도 이 능에 드나드는 사람이 집어 간 것이지, 딴 사람이야 어떻게 집어 갔을 리가 있나…….’ 하는 생각은 누구나 다 마찬가지었으나, 자기들 중에 누가 ‘내가 집어 갔습니다.’ 하고 자백하는 사람은 도무지 없고, 나중에는 능에 드나드는 사람의 집집을 모조리 뒤져 보았으나, 그래도 그릇은 나오지 않아서 인제는 도저히 찾아낼 도리가 없었습니다.

하루는 앓아 누웠던 참봉이 벌떡 일어나 어디인지 갔다가 저녁때에야 돌아 오더니, 오는 길로 능 안에 드나드는 모든 사람을 불러 모았습니다. ‘무슨 일일까? 무슨 일일까’ 하고 눈이 둥글하여 모여 가서 앉았으니까,

“여보게, 오늘 내가 성 안에 갔다가 신통한 것을 얻어 가지고 왔네.”

하므로 점점 더 이상하게들 생각했습니다.

“다른 것이 아니라 산 두꺼비 한 마리를 가지고 왔는데, 이 두꺼비는 몹시 영특한 두꺼비여서 죄진 사람을 보면 그 손가락을 꽉 문다네……. 그래 무엇이든지 잃어버린 것이 있으면 그 두꺼비가 꼭꼭 집어 간 사람을 아르켜 낸다네그려. 그래 내가 그것을 오늘 하루만 빌려 달라고 하여 간신이 얻어 가지고 왔으니, 오늘 밤에 저녁 먹고 이 방으로 다 모이게. 그래서 이번은 그릇을 집어 간 사람이 우리들 중에 있는지 없는지 시험해 보세. 그래야 우리들 마음이 편하지 않겠나.”

여러 사람들은 이 때까지, ‘저놈이 집어가지 않았을까?’ 하고 서로 서로 의심하고 또 의심받고 지내던 판이라, 마음이 껄끔한 판에 잘 되었다 생각하고 모두 두말없이 저녁 먹고 모이기로 하였습니다.

그 날 밤이 되었습니다. 모두들 모여서 쭉 둘러 앉았습니다.

참봉은 방의 불을 끄고 컴컴한 방 한복판에 큰 동이(물그릇)를 갖다 놓고,

“자아, 이 가운데 동이에 물을 부어다 놓았습니다. 이 동이 물 속에 그 두꺼비가 들어 있으니, 차례차례 이 동이의 물 속에 손가락 하나씩 넣어 보십시다. 물리지 않으면 좋고, 물리는 사람이 있으면 그이가 집어 간 것이니까요……. 자아, 내가 먼저 넣어 보리다.”

참봉은 자기 손가락을 먼저 물 속에 넣어 놓고,

“자아, 내 다음 문선이 자네가 넣어 보게.”

“네, 넣었습니다.”

“그럼, 그 다음 성팔이 자네 넣게.”

“네, 넣었습니다. 물지 않습니다.”

“그럼, 또 그 다음 아무개.”

이렇게 어두운 방 속에서 참봉이가 이름을 부르는 대로 차례차례 손가락을 넣고 하여, 쭈욱 돌아가면서 모두 한 손가락씩 물 속에 잠그고 앉았습니다.

모두들 가슴이 두근두근하였습니다. 혹시 두꺼비란 놈이 까닭 없이 내 손가락을 물면 도적 누명을 쓰겠으니까, 공연히 겁이 나서 두근두근하고 앉았습니다.

“모두들 넣었나? 안 넣은 사람 없나?”

“네, 모두 넣었습니다.”

“그런데, ‘아얏’ 소리가 나지 않으니 아무도 물리는 사람이 없는 모양일세 그려……. 그럼 우리들 중에 집어가지 않은 것이 분명하니, 마음이 우선 시원하이…….”

하고 다시 말을 이어,

“인제 그만 다 손을 빼고 불을 켜게.”

명령이 내리니까 일제히 손가락을 빼고, 한 사람이 등잔에 불을 켜 놓았습니다.

동이의 물은 그냥 물이 아니라 물감을 풀어 놓아 파란 물이었으므로 물에 넣었던 손가락 하나씩이 모두 새파랗게 물이 들었습니다. 그런데 참봉이 눈치 빠르게 살펴보니까, 그 중에 단 한 사람이 아무 손가락도 파랗지 않은 사람이 있으므로, 그 사람을 넌지시 쿡 찔러 다른 방으로 데리고 갔습니다.

