“아니오, 추워서 얼어죽어도 왕자님 곁에 있겠습니다.”

하고, 제비는 눈먼 왕자님 앞에서 잤습니다.

그 이튿날 아침때가 되었습니다. 인제는 남쪽 나라에도 아니 가기로 결심하였습니다. 느릿느릿 날아서 거리를 돌아다녔습니다. 다니면서 보니까, 욕심 많은 부자가 훌륭한 대궐 같은 집에서 즐겁게 지내는데, 그와는 딴판으로 그 집 문간에는 불쌍한 거지가 밥을 달라고 애걸을 하고 있습니다. 또 어디는 가니까, 남의 집 처마 밑에서 어린애들이 손가락을 빨아먹으면서 밥을 달라 울고 있었습니다. 또 어디는 가니까, 아들 없는 노인이 살이 드러나는 찢어진 홑옷을 입고 벌벌 떨면서 남의 집 쓰레기통을 뒤지는 이도 있었습니다.

이 불쌍한 꼴을 보고 온 제비는 왕자님께 모두 보고 온 대로 이야기를 하였습니다. 그러니까, 왕자님이

“내 몸을 금으로 쌌으니 그것을 조각조각 벗겨다가 불쌍한 사람들에게 주어다구.”

하였습니다.

이번에는 싫단 말 아니하고, 제비가 그 금 조각을 하나씩 하나씩 벗겼습니다. 아름답고 찬란하였던 복 많은 왕자는 기어이 아무 광채 없는 잿빛으로 변하고 말았습니다. 제비는 그 금 조각을 하나씩 하나씩 불쌍한 사람들에게 갖다 주었습니다.

그 후부터 얼굴빛이 누렇고 푸르고 한 가난한 사람들도 복스러워지고, 구차한 집 아이들도 장미꽃같이 활짝 피어서, 기껍게 복스럽게 놀게 되었습니다.

얼마 아니 있어 쌀쌀한 바람이 사정없이 불어오고, 아침저녁으로 서리가 하얗게 내리게 되었습니다. 벌써 함박눈이 쏟아지고, 지붕마다 길다란 얼음이 매달리게 되었습니다. 가엾은 제비는 추워서 견딜 수 없이 되었습니다. 그러나, 그렇다고 눈먼 왕자님을 버리고 혼자 가고 싶지는 않았습니다.

날이 점점 추워지자, 제비는 인제 죽을 날이 가까워 온 줄을 알았습니다. 그러나, 아직 왕자님의 어깨 위에 올라 앉을 만큼은 기운이 남아 있었습니다. 그래서, 왕자님 어깨 위에 올라 앉아서,

“왕자님, 안녕히 계십시오. 왕자님의 손에 입이나 한 번 맞추게 해 주십시오.”

하는데, 벌써 눈에서는 눈물이 펑펑 쏟아집니다. 왕자님의 눈에서도 두 줄기의 눈물이 비오듯 흐르며,

“아아, 어여쁜 제비야, 따뜻한 남쪽 나라로 가련? 아무쪼록 몸 성히 잘 가거라…….”

“아아니오. 저의 가는 곳은 남쪽 나라가 아닙니다. 저는 죽음의 나라로 갑니다. 영영 다시 뵈옵지 못할 길로 떠나갑니다. 부디 안녕히 계십시오. 왕자님!”

“오오, 제비야…….”

“아아, 왕자님…….”

눈물이 비오듯 합니다.

기어이 제비는 마지막으로 날아서 눈 감은 왕자님의 입술에 입을 맞추고, 그만 숨이 끊어졌습니다.

제비가 죽던 바로 그 때, 무엇인지 떨어져 깨지는 소리가 들렸습니다. 그것은 납으로 만든 왕자의 가슴 속 심장이 떨어져 쪼개지는 소리였습니다. 왕자님의 빛은 더 거칠어져 흉하게 되었는데, 밤에 서리가 하얗게 내렸습니다.

그 이튿날 아침때, 이 곳의 시장이 왕자가 서 있는 높은 돌기둥 밑을 지나가다 언뜻 쳐다보고,

“에그, 복 많은 왕자의 상이 왜 저렇게 더럽고 흉해졌나.”

하였습니다.

“보석도 금강석도 다 없어지고, 아주 거지꼴이 되었구나. 이대로 둘 수 없다…….”'),
  ('0000b113-0000-4000-8000-000000000113', 3, '3장',
   '고 혼자 중얼거리다 보니까, 그 밑에 조그만 제비가 죽은 것이 있었습니다. 그러나, 그리 대단하게 여기지 않아 곧 영을 내려서, 왕자의 상을 내려서 풀뭇간(대장간) 도가니 속에 넣고 녹였습니다. 그러나, 이상하게도 그 납으로 만든 심장만은 영영 녹지를 아니하여, 그냥 그 심장만은 그냥 쓰레기통에 버렸는데, 마침 그 쓰레기통 속에는 제비 죽은 송장이 내버려져 있었습니다. 그래서, 죽은 제비와 왕자의 심장은 한 쓰레기통 속에 있었습니다.

이 소문이 쫙 퍼지자, 그중 제비에게서 보석 받은 사람들이 몰려와서 그 이야기를 모두 해서, 세상 사람들이 다 알고 참 신기한 일이라고, 또 그런 착한 왕자와 제비는 다시 없다고 전보다 더 좋게 더 좋은 보석을 박아서 왕자의 상을 만들어서 세웠는데, 이번에는 특별히 왕자의 어깨 위에 제비까지 만들어 앉혔습니다. 그리고, 제비의 눈도 좋은 금강석으로 박았습니다.

날마다 사람들이 그 밑에 모여서 절을 하고, 재미있게 놉니다. 대대로 그 이야기가 전하고 영원토록 왕자와 제비의 상은 세상 사람의 존경과 사랑 속에 싸여 늘 봄철이고, 늘 젊어 늙지 아니하였습니다.'),
  ('0000b114-0000-4000-8000-000000000114', 1, '1장',
   '벌써 여러 해 전 일이었습니다. 쌀쌀한 바람 부는 섣달 어느 날 아침에, 영국 리버풀이라는 항구에서 큰 기선 한 척이 먼 길을 떠나 출범하였습니다. 그 기선에는 육십 명의 사공들과 손님 이백 명이 탔는데 선장과 모든 일꾼은 거의 모두 영국 사람이고, 손님 중에는 이탈리아 사람이 몇 사람 있었습니다. 배는 지금 몰타라는 섬을 향하고 먼 길을 떠나는데 그날 천기가 괴상하여 하늘 모양이 무엇이 오실 듯하였습니다.

기선 한 편 끝쪽에 있는 삼등객 중에 나이 열두 살 된 이탈리아 소년이 한 사람 있었습니다. 나이로 보아서는 몸과 키가 좀 작은 편이었으나, 그러나 퍽 똑똑하고 영리하고 어여쁘게 생긴 귀여운 소년이었습니다, 앞에 있는 큰 돛대 옆에 다만 홀로 밧줄을 감아 놓은 위에 걸터 앉아서 모서리가 다 해진 헌 가방에 한 손을 걸치고 있었습니다.

머리털은 어깨에까지 내려오고 다 낡은 웃옷을 어깨에 걸치고……. 보기에도 구차한 집 아이 같은 그 소년이 가만히 혼자 앉아서, 다른 손님들과 배 일꾼과 다른 조그만 배의 지나가는 것들을 물끄러미 보고 앉았는 얼굴은 무슨 근심과 걱정이 많이 있는 것같이 보여서 요새 집안에 무슨 불행한 일을 당한 것 같았습니다.

참으로 이 소년은 가련한 신세였습니다. 소년에게는 부모가 모두 돌아가시고 아니 계셨습니다. 어머님은 벌써 예전에 돌아가시어 아니 계시고 다만 혼자 길러 주신 아버님은 리버풀에서 어느 공장 직공으로 다니셨는데 수일 전에 불행하게도 이 소년 하나를 두고 마저 돌아가셨습니다. 그래서, 부모도 형제도 없는 이 가련한 소년을 그 곳에 있는 이탈리아 영사가 주선을 하여서 소년의 고향인 파델모의 먼 친척되는 아주머님께로 보내 주게 된 것이었습니다. 객지에서 부친을 마저 잃고 어이없는 고아가 되어 먼 고향의 친하지도 못한 아주머님께 길리우러 가는 어린 소년의 가슴이 얼마나 애닯고 슬펐겠습니까?

험한 하늘, 사나운 물결을 박차면서 기선은 자꾸 달아납니다. 출범한 지 얼마 안 되어서 머리털 흰 이탈리아 사람 늙은 수부가 조그만 소녀 한 사람의 손목을 잡고 이 쪽 소년의 앞으로 오더니 소년을 보고,

“마리오야, 좋은 길동무가 생겨서 인제 심심치 않겠다.”

하고는,

“너, 마리오하고 여기서 놀고 있거라.”

소녀에게도 이르고는 바쁜 듯이 돌아갔습니다.

소녀는 나이가 소년과 어상반한 어여쁜 계집애였습니다. 소년이 앉은 옆의 밧줄 위에 앉아서 둘이 서로 물끄러미 보다가,

“어디로 가니?”

하고, 소년이 먼저 물어 보았습니다.

“몰타로 가서 거기서 또 나폴리로 간단다.”

이렇게 소녀는 대답하고 또 이어서,

“어머니, 아버지한테로 간단다. 지금 어머니, 아버지가 고대 고대하고 계셔요…….”

소년은 그 말을 듣더니 고개를 숙이고 아무 말도 아니 하였습니다.

한 분 계시던 아버님까지 마저 잃고 홀로 되어서 남에게로 길리우러 가는 소년 마리오가 그 소리를 듣고 얼마나 부럽고 서러웠겠습니까?

가련한 소년 마리오는 고개를 숙이고 아무 말도 없었습니다.

조금 지난 후에 그는 주머니에서 면보(빵)를 내어서 소녀에게 같이 먹자고 권하였습니다. 소녀도 주머니에서 과자를 내어 놓으며 같이 먹자 하였습니다. 소녀의 이름은 줄리엣이라 하였습니다.

둘이는 퍽 정답게 이야기하면서 과자와 면보를 먹고 있었습니다.

“야아! 탈났다. 저 물결 보아라!”

하면서, 아까 그 이탈리아 늙은 선원이 황급히 지나가면서 두 아이를 보고,

“주의하고 있거라, 배가 몹시 흔들릴 것이니…….”

하고, 일러 두고는 또 급히 뛰어갔습니다. 하늘은 점점 괴상하여지고 바람은 점점 사납게 불며 배가 몹시 흔들리기 시작하였습니다.

그러나, 두 아이는 배멀미가 나지 않고 아무 염려도 없이 태연히 앉아서 이야기에 재미를 붙이고 있었습니다. 줄리엣은 연해 방글방글 웃고 있었습니다. 키는 마리오 소년보다 조금 크고 몸은 가늘어 어떻게 보면 병든 아이 같기도 하였습니다. 머리는 그다지 길지 않고 곱슬곱슬하고 머리 위에는 빨간 모자를 쓰고 있었습니다.

둘이서는 과자를 먹어 가면서 서로 신세 이야기를 시작하였습니다. 마리오는 어머니 아버지가 안 계신 일, 지금 친지도 아닌 먼 일갓집으로 길리우러 가는데 그나마 그 곳에서 반갑게 대해 줄지는 모르는 일을 일일이 자세하게 말했습니다. 소녀 줄리엣은 마리오의 애달픈 신세를 듣고 눈물이 눈에 고여서 퍽 언짢아했습니다. 그러나, 줄리엣은 역시 그다지 즐겁고 행복스러운 신세는 아니었습니다.

이탈리아에 있는 줄리엣의 생가집은 부모님은 계시지만 몹시 구차하였습니다. 그런데, 줄리엣의 고모님 한 분이 영국 서울 런던에 사시는데 과부로 아드님도 따님도 없고 하여서 친정집 줄리엣을 데려다 길렀습니다. 줄리엣의 부모님은 줄리엣을 보내 놓고, 그 고모님이 돌아가시면 그 집 재산을 모두 물려받아서 자기 딸이 큰 부자가 될 줄 믿고 계십니다. 그런데, 그 고모님은 두어 달 전에 마차에 치어 돌아가시고, 남은 재산이라고는 한 푼도 없었습니다. 그래서, 줄리엣도 객지에서 혼자 떨어진 몸이 되어 오도가도 못하게 된 것을 역시 이 곳에 와 있는 이탈리아 영사가 주선해 주어서 마리아와 같이 돈도 없이 이 기선에 타고 가게 된 것이었습니다.

“그래서…….”

하고, 소녀는 이야기를 계속하였습니다.

“아버지하고 어머니는 집에서 지금 내가 부자가 되어 오는 줄 알고 계시단다. 그러나 나는 돈 한 푼 없이 그냥 가난뱅이 이대로 돌아간단다. 그래도 여전히 귀여워는 하셔요. 나를 낳아 주신 아버지이구 어머니이니까……. 우리 형제도 그래요. 사형제인데 모두 내 동생이고 내가 제일 큰 형이란다. 아침이면 옷도 내가 모두 입혀주고 그래서 애들이 나를 보면 퍽 좋아한단다.”

“에그, 저 바다 보아!”

하고는, 바다를 보고는 다시 풀이 없이 앉아 있는 마리오를 보고 퍽 딱해 하는 마음으로 물었습니다.

“그래, 너는 그 친하지도 못하다는 일갓집으로 가서 살게 되니?”

“으응, 그나마 길러나 줄는지 모른단다.”

“그 집에서 너를 귀여워하지 않니?”

“어떨는지……. 그의 집도 구차하고 어린애가 많다는데…….”

“에그, 너를 미워하면 어떡하니…….”

소녀는 또 눈이 젖었습니다.

그리고, 둘이는 이런 얘기, 저런 얘기 어린이끼리 이야기에 재미를 붙이고 있었습니다. 다른 손님들이 이 두 아이를 한 남매로 알고 있었습니다.

이야기를 다 하고는 줄리엣은 실을 꺼내서 주머니를 짜고 있고, 마리오는 잠잠히 무슨 생각에 잠겨 있었습니다.

바다는 점점 갈수록 사나워졌습니다. 밤이 되니까, 물결이 더 험하게 일어나고, 바람이 더 몹시 사납게 되었습니다. 손님들은 무서워서 꼼짝 않고 선실 속에 푹 들어 앉았습니다. 둘이서는 각각 가서 자려고 헤어질 때에 줄리엣이 먼저 마리오에게 인사하였습니다.

“마리오야, 잘 자거라.”

그 때에 수부가 또 지나가면서,

“이렇게 험해서는 아무도 밤에 잠을 못 잔다.”

고, 소리치고는 바삐 뛰어갔습니다. 마리오는 줄리엣에게,

“잘 자거라!”

