노동 숙박소에 대해서 미주알고주알 묻고 나서,

"시방 가면 무슨 일자리를 구하겠는기요."

라고 그는 매달리는 듯이 또 재우쳤다.

"글쎄요, 무슨 일자리를 구할 수 있을는지요."

나는 내 대답이 너무 냉랭하고 불친절한 것이 죄송스러웠다. 그러나 일자리에 대하여 아무 지식이 없는 나로서는 이 외에 더 좋은 대답을 해줄 수가 없었던 것이다. 그 대신 나는 은근하게 물었다.

