"흥, 고향에서 오누마."

하고 그는 휘 한숨을 쉬었다. 그러자 그의 신세타령의 실마리는 풀려 나왔다. 그의 고향은 대구에서 멀지 않은 K군 H란 외딴 동리였다. 한 백 호 남짓한 그곳 주민은 전부가 역둔토를 파먹고 살았는데 역둔토로 말하면 사삿집 땅을 붙이는 것보다 떨어지는 것이 후하였다. 그러므로 넉넉지는 못할망정 평화로운 농촌으로 남부럽지 않게 지낼 수 있었다. 그러나 세상이 뒤바뀌자 그 땅은 전부가 동양척식회사의 소유에 들어가고 말았다. 직접으로 회사에 소작료를 바치게나 되었으면 그래도 나으련만 소위 중간 소작인이란 것이 생겨나서 저는 손에 흙 한 번 만져 보지도 않고 동척엔 소작인 노릇을 하며 실작인에게는 지주 행세를 하게 되었다. 동척에 소작료를 물고 나서 또 중간 소작인에게 긁히고 보니 실작인의 손에는 소출의 삼 할도 떨어지지 않았다. 그 후로 ''죽겠다'', ''못 살겠다'' 하는 소리는 중이 염불하듯 그들의 입길에서 오르내리게 되었다. 남부여대하고 타처로 유리하는 사람만 늘고 동리는 점점 쇠진해 갔다.

