"모친꺼정 돌아갔구마" "돌아가실 때 흰 죽 한 모금 못 자셨구마" 하고 이야기하던 이는 문득 말을 뚝 끊는다. 그의 눈이 번들번들함은 눈물이 쏟아졌음이리라. 나는 무엇이라고 위로할 말을 몰랐다. 한동안 머뭇머뭇이 있다가 나는 차를 탈 때에 친구들이 사준 정종병 마개를 빼었다. 찻잔에 부어서 그도 마시고 나도 마셨다. 악착한 운명이 던져 준 깊은 슬픔을 술로 녹이려는 듯이 연거푸 다섯 잔을 마신 그는 다시 말을 계속하였다. 그 후 그는 부모 잃은 땅에 오래 머물기 싫었다. 신의주로 안동현으로 품을 팔다가 일본으로 또 벌이를 찾아가게 되었다. 구주 탄광에 있어도 보고 대판 철공장에도 몸을 담아 보았다. 벌이는 조금 나았으나 외롭고 젊은 몸은 자연히 방탕해졌다. 돈을 모으려야 모을 수 없고 이따금 울화만 치받치기 때문에 한곳에 주접을 하고 있을 수 없었다. 화도 나고 고국 산천이 그립기도 하여서 훌쩍 뛰어나왔다가 오래간만에 고향을 둘러보고 벌이를 구할 겸 서울로 올라가는 길이라 한다.

