"참! 가슴이 터지드마, 가슴이 터져."

하자마자 굵직한 눈물 둬 방울이 뚝뚝 떨어진다.

나는 그 눈물 가운데 음산하고 비참한 조선의 얼굴을 똑똑히 본 듯싶었다.

이윽고 나는 이런 말을 물었다.

"그래, 이번 길에 고향 사람은 하나도 못 만났습니까."

"하나 만났구마, 단지 하나."

"친척 되시는 분이던가요."

"아니구마, 한이웃에 살던 사람이구마."

하고 그의 얼굴은 더욱 침울해진다.

"여간 반갑지 않으셨겠지요."

"반갑다마다, 죽은 사람을 만난 것 같더마. 더구나 그 사람은 나와 까닭도 좀 있던 사람인데……."

"까닭이라니?"

"나와 혼인말이 있던 여자구마."

"하―!"

나는 놀란 듯이 벌린 입이 닫혀지지 않았다.

"그 신세도 내 신세만이나 하구마."

하고 그는 또 이야기를 계속하였다. 그 여자는 자기보다 나이 두 살 위였는데 한이웃에 사는 탓으로 같이 놀기도 하고 싸우기도 하며 자라났었다. 그가 열네 살 적부터 그들 부모 사이에 혼인말이 있었고 그도 어린 마음에 매우 탐탁하게 생각하였었다. 그런데 그 처녀가 열일곱 살 된 겨울에 별안간 간 곳을 모르게 되었다. 알고 보니 그 아비 되는 자가 이십 원을 받고 대구 유곽에 팔아먹은 것이었다. 그 소문이 퍼지자 그 처녀 가족은 그 동리에서 못 살고 멀리 이사를 갔는데 그 후로는 물론 피차에 한 번 만나 보지도 못하였다. 이번에야 빈터만 남은 고향을 구경하고 돌아오는 길에 읍내에서 그 아내 될 뻔한 댁과 마주치게 되었다. 처녀는 어떤 일본 사람 집에서 아이를 보고 있었다. 궐녀는 이십 원 몸값을 십 년을 두고 갚았건만 그래도 주인에게 빚이 육십 원이나 남았었는데 몸에 몹쓸 병이 들고 나이 늙어져서 산송장이 되니까 주인 되는 자가 특별히 빚을 탕감해 주고 작년 가을에야 놓아 준 것이었다. 궐녀도 자기와 같이 십 년 동안이나 그리던 고향에 찾아오니까 거기에는 집도 없고 부모도 없고 쓸쓸한 돌무더기만 눈물을 자아낼 뿐이었다. 하루 해를 울어 보내고 읍내로 들어와서 돌아다니다가 십 년 동안에 한 마디 두 마디 배워 두었던 일본 말 덕택으로 그 일본 집에 있게 되었던 것이었다.

"암만 사람이 변하기로 어째 그렇게도 변하는기오? 그 숱 많던 머리가 훌렁 다 벗어졌더마. 눈은 푹 들어가고 그 이들이들하던 얼굴빛도 마치 유산을 끼얹은 듯하더마."

"서로 붙잡고 많이 우셨겠지요."

"눈물도 안 나오드마. 일본 우동집에 들어가서 둘이서 정종만 열 병 따라 뉘고 헤어졌구마."

하고 가슴을 짜는 듯이 괴로운 한숨을 쉬더니만 그는 지낸 슬픔을 새록새록이 자아내어 마음을 새기기에 지쳤음이더라.

"이야기를 다 하면 무얼 하는기오."

하고 쓸쓸하게 입을 다문다. 내 또한 너무도 참혹한 사람살이를 듣기에 쓴물이 났다.

"자, 우리 술이나 마저 먹읍시다."

하고 우리는 서로 주거니 받거니 한 되 병을 다 말리고 말았다. 그는 취흥에 겨워서 우리가 어릴 때 멋모르고 부르던 노래를 읊조렸다.

